const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const nyc = ee.Geometry.Point([-74.0060, 40.7128]);

  const date2024 = '2024-06-24';
  const date2025 = '2025-06-24';

  // 2. Data Acquisition
  // Use ERA5-Land hourly data for temperature at 2m
  const collection2024 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(date2024, '2024-06-25')
    .select('temperature_2m');

  const collection2025 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
    .filterDate(date2025, '2025-06-25')
    .select('temperature_2m');

  // Check collection sizes
  const size2024 = collection2024.size().getInfo();
  const size2025 = collection2025.size().getInfo();

  console.log(`2024 Images: ${size2024}`);
  console.log(`2025 Images: ${size2025}`);

  // If either collection is empty, we cannot compare
  if (size2024 === 0 || size2025 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing: Get maximum temperature for each day
  const maxTemp2024Img = collection2024.max();
  const maxTemp2025Img = collection2025.max();

  // Reduce to get the temperature value at NYC
  const reducer = ee.Reducer.max();
  const scale = 1000;

  const maxTemp2024 = maxTemp2024Img.reduceRegion({
    reducer: reducer,
    geometry: nyc,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  const maxTemp2025 = maxTemp2025Img.reduceRegion({
    reducer: reducer,
    geometry: nyc,
    scale: scale,
    maxPixels: 1e9
  }).get('temperature_2m').getInfo();

  // Check for valid numbers
  if (maxTemp2024 === null || maxTemp2025 === null || 
      isNaN(maxTemp2024) || isNaN(maxTemp2025)) {
    console.log("Invalid temperature values (null or NaN).");
    console.log("<answer>C3</answer>");
    return;
  }

  // Temperature in ERA5 is in Kelvin. Convert to Celsius for readability? 
  // But comparison can be done in Kelvin as well.
  const temp2024 = maxTemp2024 - 273.15; // Convert K to C
  const temp2025 = maxTemp2025 - 273.15;

  // Validate temperature range (reasonable range for Earth)
  if (temp2024 < -100 || temp2024 > 100 || temp2025 < -100 || temp2025 > 100) {
    console.log("Temperature out of valid range.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`2024 Max Temp: ${temp2024.toFixed(2)}°C`);
  console.log(`2025 Max Temp: ${temp2025.toFixed(2)}°C`);

  // 4. Comparison
  if (temp2025 > temp2024) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
